package test;

import java.text.MessageFormat;

public class Test {
    public void method() {
        String label = "Count: {0}";
        int limit = 10;
        // This uses java.text.MessageFormat, which should not be affected.
        String formatted = MessageFormat.format(label, new Object[]{new Integer(limit)});
        System.out.println(formatted);

        // This is a different method signature, not covered by the rule.
        String someOtherFormatted = org.eclipse.search2.internal.ui.Messages.format(label, new Object[]{new Integer(limit), "extra"});
        System.out.println(someOtherFormatted);
    }
}
